class OriginalDrivers(unittest.TestCase):
    def test_first_policy_refusals_preserve_preimages_and_explicit_review(self):
        stored = (bundle.ROOT / 'tests/fixtures/authoring_sessions/ci-native-drivers-v030/first-policy.json.gz').read_bytes()
        self.assertEqual(bundle.digest(stored), '332568ca403e2b7c91a37282afb6259f555618ac5f02f8a1b5eb4ad0eea5110b')
        with gzip.GzipFile(fileobj=io.BytesIO(stored)) as stream:
            raw = stream.read(822_844)
        self.assertEqual(len(raw), 822_843)
        self.assertEqual(bundle.digest(raw), '442afa0b2732cd79ed3eed78c58c86b8e0e6acc4d45ead655ac1305c0274557d')
        record = json.loads(raw)
        self.assertEqual(record['format'], 'qleisli.native-driver-first-policy-refusals')
        self.assertEqual(len(record['records']), 8)
        files = {}
        for name, row in record['records'].items():
            data = base64.b64decode(row['base64'], validate=True)
            self.assertEqual((len(data), bundle.digest(data)), (row['bytes'], row['sha256']))
            files[name] = data
        self.assertEqual(json.loads(files['preflight-v1.json'])['status'], 'failed')
        self.assertEqual(json.loads(files['integrity-v1.json'])['status'], 'failed')
        self.assertIn(b'frozen source changed', files['integrity-v1-command0.log'])
        review = json.loads(files['source-review-first.json'])
        self.assertEqual(len(review['sources']), 4)
        self.assertTrue(all('Complete original Python AST preserved' in row['review'] for row in review['sources']))

    def test_generation_closure_changes_without_dropping_full_fixture_input_identity(self):
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            contents = {'scripts/driver.py': 'driver', 'scripts/helpers/codec.py': 'codec',
                        '.github/ci/native-comparisons.json': '{}', '.github/ci/source-checks.json': '{}',
                        'tests/fixtures/input.json': 'original fresh test payload'}
            for name, text in contents.items():
                path = root / name
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text(text)

            def git(command, **kwargs):
                if command[1] == 'rev-parse':
                    return 'a' * 40 + '\n'
                self.assertEqual(command[1], 'ls-files')
                return b'\0'.join(name.encode() for name in contents) + b'\0'

            with mock.patch.object(bundle, 'ROOT', root), mock.patch.object(bundle.subprocess, 'check_output', side_effect=git):
                code = bundle.generation_binding()
                invocation = bundle.ci_source_checks.snapshot(root)
                (root / 'tests/fixtures/input.json').write_text('new fresh test payload')
                self.assertEqual(bundle.generation_binding(), code)
                self.assertNotEqual(bundle.ci_source_checks.snapshot(root), invocation)
                (root / 'scripts/helpers/codec.py').write_text('changed transitive generation helper')
                self.assertNotEqual(bundle.generation_binding(), code)

    def test_first_shadow_failure_retains_complete_and_unexecuted_scopes(self):
        stored = (bundle.ROOT / 'tests/fixtures/authoring_sessions/ci-native-drivers-v030/first-comparison.json.gz').read_bytes()
        self.assertEqual(bundle.digest(stored), 'db9c44eb1b0daf93b5a7a6e249dd053c126a98a0f20b28a5f5bdf04055b934d1')
        with gzip.GzipFile(fileobj=io.BytesIO(stored)) as stream:
            raw = stream.read(130_821)
        self.assertEqual(len(raw), 130_820)
        self.assertEqual(bundle.digest(raw), '5e7906686e0d7438327bf44c05ff255f36d0b4b738b2157834702e89f0d2a29a')
        record = json.loads(raw)
        self.assertEqual(record['status'], 'partial-failure-not-full-shadow-success')
        self.assertEqual(len(record['records']), 16)
        files = {}
        for name, row in record['records'].items():
            data = base64.b64decode(row['base64'], validate=True)
            self.assertEqual((len(data), bundle.digest(data)), (row['bytes'], row['sha256']))
            files[name] = data
        observed = [json.loads(files['lean-interference-' + mode + '/observed-native.json'])[0]
                    for mode in ('standalone', 'shared')]
        self.assertEqual({k: v for k, v in observed[0].items() if k != 'command'},
                         {k: v for k, v in observed[1].items() if k != 'command'})
        self.assertEqual(json.loads(files['lean-qft-semantic-standalone/observed-native.json'])[0]['exit_code'], 0)
        self.assertIn(b"NameError: name 'upper' is not defined", files['lean-qft-semantic-standalone/stderr.txt'])
        self.assertFalse(any(name.startswith('lean-qft-semantic-shared/') for name in files))

    def test_first_combined_compile_refusal_is_retained_without_test_success(self):
        stored = (bundle.ROOT / 'tests/fixtures/authoring_sessions/ci-native-drivers-v030/first-compilation.json.gz').read_bytes()
        self.assertEqual(bundle.digest(stored), '9eacf796ce40c5f0da8a65ea4fa8f56b3aa8ccb558a7bd6e4ac39a86416f62a1')
        with gzip.GzipFile(fileobj=io.BytesIO(stored)) as stream:
            raw = stream.read(1_009_116)
        self.assertEqual(len(raw), 1_009_115)
        self.assertEqual(bundle.digest(raw), 'd1ee1059ae3cbb0149dc698a4e0d08fa9284bc31d7f8f1974ec1b65c5a0bcf54')
        record = json.loads(raw)
        self.assertEqual(record['format'], 'qleisli.native-driver-first-compilation')
        self.assertEqual(len(record['records']), 6)
        files = {}
        for name, row in record['records'].items():
            data = base64.b64decode(row['base64'], validate=True)
            self.assertEqual((len(data), bundle.digest(data)), (row['bytes'], row['sha256']))
            files[name] = data
        observation = json.loads(files['preparation-first.json'])
        self.assertEqual(observation['status'], 'failed')
        self.assertEqual(observation['before'], observation['after'])
        commands = [row for row in observation['commands'] if 'command' in row]
        self.assertEqual([row['exit'] for row in commands], [0, 0, 1])
        self.assertIn('Unknown constant `IO.getArgs`', commands[-1]['stdout'])
        self.assertIn(b'match (\xe2\x86\x90 IO.getArgs) with', files['Main.lean'])

    def test_original_sources_and_first_refusals_remain_bounded_inert_records(self):
        stored = (bundle.ROOT / 'tests/fixtures/authoring_sessions/ci-native-drivers-v030/first.json.gz').read_bytes()
        self.assertEqual(bundle.digest(stored), 'fc386407b882f08962f884b80a58f9780d4f136922b2ed5c808da6f5860c70cb')
        with gzip.GzipFile(fileobj=io.BytesIO(stored)) as stream:
            raw = stream.read(1_177_132)
        self.assertEqual(len(raw), 1_177_131)
        self.assertEqual(bundle.digest(raw), 'a9df34bc5fb3a2852f27d435cbeae8d2b5e7d1e6e1300733bbd129c2c28d2c6b')
        record = json.loads(raw)
        self.assertEqual((record['format'], record['version'], record['status']),
                         ('qleisli.native-driver-first', 1, 'original-source-and-refactor-diagnostics-only'))
        self.assertEqual(len(record['records']), 19)
        files = {}
        for name, row in record['records'].items():
            data = base64.b64decode(row['base64'], validate=True)
            self.assertEqual((len(data), bundle.digest(data)), (row['bytes'], row['sha256']))
            files[name] = data
        index = json.loads(files['index.json'])
        self.assertEqual(index['status'], 'captured-not-compiled-or-executed')
        self.assertEqual(set(index['drivers']), set(ORIGINAL))
        for name, expected in ORIGINAL.items():
            self.assertEqual(bundle.digest(files[index['drivers'][name]['path']]), expected)
        self.assertIn(b"AssertionError: ('exact', 3)", files['refactor-first-refusal.json'])
        self.assertIn(b'AssertionError: lean-qft', files['qft-builder-first/diagnostic.json'])
        packed = base64.b64decode(record['original_static_record']['base64'], validate=True)
        self.assertEqual(bundle.digest(packed), '8304c4822f1de7971d31e3e536d0332ada6c9fde1527ac875364ad64bf2e8a92')
        with gzip.GzipFile(fileobj=io.BytesIO(packed)) as stream:
            static = stream.read(415_532)
        self.assertEqual(len(static), 415_531)
        self.assertEqual(bundle.digest(static), '4c91b61b995e32bfba0fc5a3b4035a6336538edace979b90a32e23edf554fb73')

    def test_compilation_preparation_cannot_report_executed_tests(self):
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            build = root / 'native-build.json'
            build.write_text('{}\n')

            def compile(project, log, **kwargs):
                path = project / 'native-test'
                path.write_bytes(b'synthetic compiler output, never executed')
                return path

            with (mock.patch.object(bundle.ci_source_checks, 'snapshot', return_value={'head': 'a' * 40, 'working_inputs_sha256': 'b' * 64}),
                  mock.patch.object(bundle, 'generation_binding', return_value={'head': 'a' * 40, 'sources': {}}),
                  mock.patch.object(native_harness, 'validate'),
                  mock.patch.object(native_harness, 'compile_driver', side_effect=compile),
                  mock.patch.object(bundle, 'generate', return_value='def main : IO Unit := pure ()\n')):
                path, checksum = bundle.prepare(root / 'prepared', ['lean-finite'], [], build)
                data = json.loads(path.read_bytes())
                self.assertEqual(data['status'], 'prepared-not-executed')
                self.assertEqual(bundle.digest(path.read_bytes()), checksum)
                self.assertNotIn('test_success', data)

    def test_every_original_generated_main_is_byte_identical(self):
        self.assertEqual(set(ORIGINAL), set(bundle.MODULES))
        for name, expected in ORIGINAL.items():
            with self.subTest(name=name):
                self.assertEqual(bundle.digest(bundle.generate(name).encode()), expected)

    def test_manifest_commands_and_subset_are_explicit(self):
        tasks = json.loads((bundle.ROOT / '.github/ci/native-comparisons.json').read_text())['tasks']
        self.assertEqual(set(bundle.task_ids(tasks)), set(ORIGINAL))
        selected = [t for t in tasks if t['id'] == 'lean-qft-semantic']
        self.assertEqual(bundle.task_ids(selected), ['lean-qft-semantic'])
        changed = copy.deepcopy(selected)
        changed[0]['commands'][0].remove('--small')
        with self.assertRaisesRegex(ValueError, 'manifest command changed'):
            bundle.task_ids(changed)
        with self.assertRaises(ValueError):
            bundle.task_ids([])

    def test_dispatch_preserves_distinct_scopes_and_unknown_selection_refuses(self):
        source = bundle.combine({'lean-finite': 'import Lean\ndef main : IO Unit := IO.println "one"\n',
                                 'lean-raw': 'import Lean\ndef main : IO Unit := IO.println "two"\n'})
        self.assertEqual(source.count('import Lean'), 1)
        self.assertIn('namespace RegressionDriver_0', source)
        self.assertIn('namespace RegressionDriver_1', source)
        self.assertIn('| ["lean-finite"] => RegressionDriver_0.main', source)
        self.assertIn('| ["lean-raw"] => RegressionDriver_1.main', source)
        self.assertIn('throw (IO.userError "unknown or missing regression driver")', source)
        for names in ([], ['unknown'], ['lean-raw', 'lean-raw']):
            with self.assertRaises(ValueError):
                bundle.identifiers(names)
        with self.assertRaises(ValueError):
            bundle.combine({'lean-raw': 'def x := 0\nimport Lean\n'})

    def test_absent_selection_compiles_and_incomplete_explicit_selection_never_falls_back(self):
        with mock.patch.dict(os.environ, {}, clear=True), mock.patch.object(native_harness, 'compile_driver') as compile:
            native_harness.build(Path('/temporary'), [], driver='lean-finite')
            compile.assert_called_once()
        for key in bundle.ENVIRONMENT:
            with mock.patch.dict(os.environ, {key: ''}, clear=True), mock.patch.object(native_harness, 'compile_driver') as compile:
                with self.assertRaises(ValueError):
                    native_harness.build(Path('/temporary'), [], driver='lean-finite')
                compile.assert_not_called()


class ArtifactSelection(unittest.TestCase):
    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory(prefix='qleisli-driver-artifact-test-')
        self.addCleanup(self.temporary.cleanup)
        self.root = Path(self.temporary.name)
        self.project = self.root / 'test-project'
        self.project.mkdir()
        self.source = 'def main : IO Unit := IO.println "actual test input"\n'
        (self.project / 'Main.lean').write_text(self.source)
        (self.root / 'driver').mkdir()
        (self.root / 'driver/Main.lean').write_text('synthetic compiled source binding\n')
        (self.root / 'driver/native-test').write_bytes(b'synthetic executable bytes; never executed')
        (self.root / 'native-build.json').write_text('{}\n')
        self.binding = {'head': 'a' * 40, 'sources': {'scripts/generator.py': 'b' * 64}}
        self.record = dict(format='qleisli.native-test-drivers', version=2, status='prepared-not-executed',
                           root=str(bundle.ROOT), binding=self.binding,
                           invocation_binding={'head': 'a' * 40, 'working_inputs_sha256': 'c' * 64},
                           build=dict(path=str(self.root / 'native-build.json'), sha256=bundle.digest(b'{}\n')),
                           drivers={'lean-finite': dict(bytes=len(self.source.encode()), sha256=bundle.digest(self.source.encode()))},
                           source=dict(path='driver/Main.lean', sha256=bundle.digest((self.root / 'driver/Main.lean').read_bytes())),
                           binary=dict(path='driver/native-test', sha256=bundle.digest((self.root / 'driver/native-test').read_bytes())))
        self.path = self.root / 'drivers.json'
        self.environment = {bundle.BUNDLE_ENV: str(self.path), bundle.SELECTOR_ENV: 'lean-finite'}
        self.write()
        patch = mock.patch.object(bundle, 'generation_binding', return_value=self.binding)
        self.snapshot = patch.start()
        self.addCleanup(patch.stop)
        patch = mock.patch.object(native_harness, 'validate')
        self.validate = patch.start()
        self.addCleanup(patch.stop)
        patch = mock.patch.object(bundle, 'generate', return_value=self.source)
        patch.start()
        self.addCleanup(patch.stop)

    def write(self):
        raw = (json.dumps(self.record) + '\n').encode()
        self.path.write_bytes(raw)
        self.environment[bundle.DIGEST_ENV] = bundle.digest(raw)

    def select(self):
        return bundle.selected(self.project, [], 'lean-finite', self.environment)

    def test_selection_uses_actual_binary_bytes_and_explicit_argument(self):
        driver = self.select()
        self.assertEqual(native_harness.argv(driver), [str(self.root / 'driver/native-test'), 'lean-finite'])
        self.assertEqual(driver.read_bytes(), (self.root / 'driver/native-test').read_bytes())
        self.validate.assert_called_once_with(self.root / 'native-build.json')

    def test_corrupt_record_cannot_update_its_own_expected_digest(self):
        self.path.write_text('{}\n')
        with self.assertRaisesRegex(ValueError, 'changed native driver record'):
            self.select()

    def test_stale_source_context_is_rejected(self):
        self.snapshot.return_value = self.binding | {'head': 'c' * 40}
        with self.assertRaisesRegex(ValueError, 'stale native driver context'):
            self.select()

    def test_source_substitution_and_changed_generator_are_rejected(self):
        (self.project / 'Main.lean').write_text('different original body\n')
        with self.assertRaisesRegex(ValueError, 'generated source differs'):
            self.select()
        self.record['drivers']['lean-finite'] = dict(bytes=24, sha256=bundle.digest(b'different original body\n'))
        self.write()
        with self.assertRaisesRegex(ValueError, 'generated source differs'):
            self.select()

    def test_missing_or_different_selector_is_rejected(self):
        for selector in ('', 'unknown', 'lean-raw'):
            self.environment[bundle.SELECTOR_ENV] = selector
            with self.assertRaises(ValueError):
                self.select()

    def test_each_actual_product_must_still_match(self):
        for name in ('driver/Main.lean', 'driver/native-test', 'native-build.json'):
            path = self.root / name
            original = path.read_bytes()
            path.write_bytes(original + b'changed')
            with self.subTest(name=name), self.assertRaises(ValueError):
                self.select()
            path.write_bytes(original)

    def test_extra_schema_fields_and_path_substitution_are_rejected(self):
        original = copy.deepcopy(self.record)
        for mutation in ('extra', 'version', 'old-format', 'binary-path', 'missing-driver'):
            self.record = copy.deepcopy(original)
            if mutation == 'extra':
                self.record['producer_success'] = True
            elif mutation == 'version':
                self.record['version'] = True
            elif mutation == 'old-format':
                self.record['version'] = 1
                self.record.pop('invocation_binding')
            elif mutation == 'binary-path':
                self.record['binary']['path'] = '../other-executable'
            else:
                self.record['drivers'] = {}
            self.write()
            with self.subTest(mutation=mutation), self.assertRaises(ValueError):
                self.select()


if __name__ == '__main__':
    unittest.main()
